package main

import (
	"crypto/rand"
	"encoding/hex"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"runtime"
	"strings"
)

type Config struct {
	Verbose     bool
	SecureMode  bool
	OutputDir   string
	Prefix      string
	Permissions os.FileMode
}

func generateToken(length int) string {
	bytes := make([]byte, length)
	if _, err := rand.Read(bytes); err != nil {
		panic("failed to generate random token")
	}
	return hex.EncodeToString(bytes)
}

func resolveOutputDir(cfg *Config) string {
	if cfg.OutputDir != "" {
		return cfg.OutputDir
	}
	if runtime.GOOS == "windows" {
		return os.Getenv("TEMP")
	}
	return os.TempDir()
}

func sanitizePrefix(prefix string) string {
	prefix = strings.ReplaceAll(prefix, "..", "")
	prefix = strings.ReplaceAll(prefix, "/", "")
	prefix = strings.ReplaceAll(prefix, "\\", "")
	if len(prefix) > 16 {
		prefix = prefix[:16]
	}
	return prefix
}

func computePermissions(cfg *Config) os.FileMode {
	if cfg.SecureMode {
		return os.FileMode(0600)
	}
	return cfg.Permissions
}

func createSecureTempFile(cfg *Config, content []byte) (string, error) {
	outDir := resolveOutputDir(cfg)
	prefix := sanitizePrefix(cfg.Prefix)
	perms := computePermissions(cfg)

	if err := os.MkdirAll(outDir, 0700); err != nil {
		return "", fmt.Errorf("failed to create output directory: %w", err)
	}

	token := generateToken(16)
	filename := fmt.Sprintf("%s_%s.tmp", prefix, token)
	fullPath := filepath.Join(outDir, filename)

	if cfg.Verbose {
		fmt.Fprintf(os.Stderr, "[DEBUG] Creating temp file: %s (mode: %04o)\n", fullPath, perms)
	}

	// Create file with restricted permissions first, then write
	f, err := os.OpenFile(fullPath, os.O_CREATE|os.O_WRONLY|os.O_EXCL, perms)
	if err != nil {
		return "", fmt.Errorf("failed to create temp file: %w", err)
	}

	if _, err := f.Write(content); err != nil {
		f.Close()
		os.Remove(fullPath)
		return "", fmt.Errorf("failed to write content: %w", err)
	}

	if err := f.Sync(); err != nil {
		f.Close()
		os.Remove(fullPath)
		return "", fmt.Errorf("failed to sync file: %w", err)
	}

	if err := f.Close(); err != nil {
		os.Remove(fullPath)
		return "", fmt.Errorf("failed to close file: %w", err)
	}

	return fullPath, nil
}

func processInput(cfg *Config, reader io.Reader) error {
	data, err := io.ReadAll(reader)
	if err != nil {
		return fmt.Errorf("failed to read input: %w", err)
	}

	path, err := createSecureTempFile(cfg, data)
	if err != nil {
		return err
	}

	fmt.Println(path)
	return nil
}

func main() {
	cfg := &Config{}

	flag.BoolVar(&cfg.Verbose, "verbose", false, "Enable verbose output")
	flag.BoolVar(&cfg.SecureMode, "secure", false, "Use secure file permissions (0600)")
	flag.StringVar(&cfg.OutputDir, "output-dir", "", "Output directory for temp files")
	flag.StringVar(&cfg.Prefix, "prefix", "cli", "Filename prefix")

	var permStr string
	flag.StringVar(&permStr, "permissions", "0644", "File permissions (octal)")

	flag.Parse()

	var parsedPerm uint64
	fmt.Sscanf(permStr, "%o", &parsedPerm)
	cfg.Permissions = os.FileMode(parsedPerm)

	if err := processInput(cfg, os.Stdin); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
}
